from produire import produire,paras,steps,table
from medicaments_suite import acetazolamide
parts=[
('La {crise aiguë de fermeture de l’angle} bloque brusquement l’évacuation de l’humeur aqueuse. La pression intraoculaire peut augmenter rapidement. Un glaucome constitué désigne une atteinte du nerf optique et n’est pas synonyme de toute crise aiguë.',paras('L’angle entre iris et cornée contient le système de drainage de l’humeur aqueuse. Lorsque l’iris empêche cet écoulement, la pression monte et peut menacer la vision en peu de temps.', 'Les HUG distinguent la crise de fermeture d’angle d’un glaucome déjà constitué. La recommandation européenne la considère comme une urgence dont le traitement rapide peut éviter des séquelles, alors qu’un retard peut entraîner une perte visuelle sévère.')),
('Le {terrain et les médicaments orientent le mécanisme}. Âge, hypermétropie et anatomie étroite de la chambre antérieure peuvent prédisposer. Une fermeture secondaire peut toutefois survenir dans un autre contexte.',paras('Les HUG citent notamment sexe féminin, âge avancé, origine asiatique et cristallin volumineux parmi les facteurs de risque. Ces associations ne suffisent pas à confirmer le diagnostic et ne fournissent pas une prévalence suisse.', 'Rechercher dilatation pupillaire récente, médicaments anticholinergiques ou sympathomimétiques et certains psychotropes. Le topiramate et certains sulfamides peuvent produire un épanchement uvéal avec poussée vers l’avant ; ce mécanisme n’est pas un simple bloc pupillaire.')),
('Le {mécanisme détermine le traitement définitif}. Un bloc pupillaire peut pousser l’iris vers l’angle. Un mécanisme cristallinien ou situé en arrière du cristallin demande une autre stratégie.',paras('Le bloc pupillaire augmente la résistance au passage de l’humeur aqueuse entre les chambres postérieure et antérieure. L’iris se bombe et ferme le drainage ; une iridotomie permet de créer un passage contournant ce bloc.', 'Un iris plateau peut laisser persister une fermeture après levée de la composante pupillaire. Un cristallin déplacé ou volumineux, un épanchement uvéal ou une mauvaise direction de l’humeur aqueuse modifient le mécanisme. La pilocarpine peut aggraver certaines de ces formes par déplacement antérieur du diaphragme iris-cristallin.')),
('Le {tri exige un transfert ophtalmologique immédiat}. Douleur intense, vision diminuée, halos et nausées doivent faire examiner l’œil. Ne pas traiter uniquement les vomissements ou la céphalée.',paras('Appeler l’équipe spécialisée dès la suspicion ; l’absence de tonomètre ne justifie pas d’attendre. Le tableau peut être pris à tort pour une migraine, un problème digestif ou une autre urgence neurologique.', 'Une plaie du globe ou une autre cause de douleur aiguë doit rester dans le diagnostic différentiel. Ne pas comprimer un œil traumatisé suspect. Un traitement initial éventuel est organisé avec l’ophtalmologue et ne retarde pas le transfert.')),
('L’{anamnèse précise le début et les facteurs déclenchants}. Demander douleur, halos, flou visuel et épisodes transitoires antérieurs. Relever tous les médicaments, y compris ceux sans ordonnance.',paras('Noter symptômes dans l’obscurité, mydriase pharmacologique, chirurgie et antécédent de crise dans l’autre œil. Les médicaments récents peuvent révéler une cause secondaire, notamment si l’atteinte est bilatérale ou accompagnée d’un changement réfractif.', 'Avant un hypotenseur général, rechercher allergies, maladie rénale ou hépatique, insuffisance cardiaque, troubles électrolytiques, grossesse et allaitement. Les vomissements influencent le choix de la voie d’administration.')),
('L’{examen recherche hypertonie et fermeture de l’angle}. Mesurer la vision et la pression, puis examiner cornée et pupille. La gonioscopie spécialisée précise l’angle et l’autre œil.',paras('Les signes classiques sont cornée œdémateuse, injection péricornéenne, chambre antérieure périphérique peu profonde et pupille semi-dilatée peu réactive. Tous ne sont pas forcément réunis au premier examen.', 'L’œdème peut gêner la gonioscopie initiale. Examiner aussi l’autre œil aide à reconnaître une prédisposition anatomique. L’examen du nerf optique et de la rétine est complété dès que possible ; la pression seule ne suffit pas à distinguer tous les mécanismes.')),
('L’{approche syndromique distingue les mécanismes d’hypertonie}. La douleur et les vomissements sont compatibles avec une fermeture aiguë. Une autre maladie peut toutefois produire un œil rouge sous pression.',table(['Contexte','Mécanisme ou diagnostic à rechercher'],[['Angle étroit, pupille semi-dilatée, symptômes aigus.','Bloc pupillaire dans une fermeture primaire possible.'],['Cristallin volumineux ou déplacé.','Composante cristallinienne ; traitement adapté.'],['Topiramate ou sulfamide, atteinte parfois bilatérale.','Épanchement uvéal et poussée postérieure possibles.'],['Inflammation, synéchies ou chirurgie antérieure.','Fermeture secondaire ou mauvaise direction de l’humeur aqueuse.'],['Néovaisseaux iriens et maladie rétinienne ischémique.','Glaucome néovasculaire, autre mécanisme urgent.'],['Atteinte cornéenne infectieuse ou uvéite.','Ne pas administrer indistinctement les mêmes collyres.']])) ,
('Le {diagnostic positif associe clinique, pression et étude de l’angle}. La gonioscopie reste essentielle pour comprendre le contact entre iris et trabéculum. Les symptômes seuls ne justifient pas un traitement uniforme.',paras('La pression peut être très élevée, mais une valeur n’identifie pas à elle seule la cause de fermeture. La recommandation européenne insiste sur l’exclusion des causes secondaires, cristalliniennes et rétrocristalliniennes avant de choisir le traitement pupillaire.', 'Une diminution après médicament ne prouve pas que l’angle est durablement ouvert. La recherche d’une atteinte du nerf optique est nécessaire pour distinguer crise et glaucome constitué et organiser le suivi.')),
('Les {examens complémentaires précisent le mécanisme et la sécurité thérapeutique}. Les investigations anatomiques ne doivent pas retarder le traitement urgent. Le bilan général dépend des médicaments envisagés.',paras('Une imagerie du segment antérieur ou une biométrie peut compléter l’évaluation, notamment pour le rôle du cristallin et la planification chirurgicale. Elle ne remplace pas systématiquement la gonioscopie.', 'Évaluer fonction rénale, électrolytes et équilibre acido-basique lorsqu’un traitement systémique le demande. Avant un agent hyperosmotique, rechercher particulièrement une maladie cardiaque ou rénale et un risque de surcharge ; cette mesure n’est pas un geste banal de cabinet.')),
('L’{algorithme associe baisse de pression et correction du mécanisme}. L’équipe urgente adapte les médicaments au terrain. Le traitement définitif est organisé dès que les conditions le permettent.',steps('Appeler l’ophtalmologue et documenter rapidement vision, médicaments et contre-indications.', 'Confirmer le mécanisme autant que possible et abaisser la pression par les traitements locaux et systémiques adaptés.', 'Réévaluer pression, cornée, état général et réponse ; le choix d’un myotique dépend du mécanisme.', 'Si bloc pupillaire, réaliser l’iridotomie dès que la cornée est suffisamment claire.', 'Si réponse insuffisante ou laser impossible, discuter avec l’équipe iridoplastie ou autre geste spécialisé.', 'Évaluer l’autre œil et organiser la prévention de récidive ainsi que le suivi du nerf optique.')),
('La {prise en charge suisse est spécialisée et immédiate}. Les hypotenseurs réduisent la pression pendant que la cause de fermeture est traitée. Le choix et l’ordre des collyres dépendent de l’examen.',paras('Les recommandations européennes privilégient des traitements qui réduisent la production d’humeur aqueuse dans la phase aiguë. Les analogues des prostaglandines ont un début d’action plus lent et ne remplacent pas les mesures urgentes.', '@@MEDICAMENTS@@', 'La pilocarpine n’est envisagée que dans le mécanisme approprié. Selon la recommandation européenne, elle peut être inefficace lorsque la pression est très élevée ou l’iris ischémique ; si la pression initiale atteint 40 mmHg ou davantage, son emploi est différé jusqu’à baisse de pression. Un mécanisme cristallinien ou rétrocristallinien peut au contraire nécessiter une cycloplégie spécialisée.', 'Une corticothérapie locale peut être choisie par l’ophtalmologue pour l’inflammation associée. Cela n’autorise pas la transposition de Maxidex présenté dans l’autre leçon, dont la notice contre-indique le glaucome. Les contre-indications et le statut d’emploi de la spécialité effectivement prescrite doivent être vérifiés.', 'Un agent hyperosmotique peut être discuté si la réponse est insuffisante, avec évaluation cardiaque, rénale et hydroélectrolytique. Aucun schéma dosé de mannitol ni de collyre hypotenseur supplémentaire n’est proposé ici sans sa notice suisse ; le protocole urgent est prescrit par l’équipe.', 'L’iridotomie traite un bloc pupillaire dès que la cornée le permet. Si l’œdème ou l’échec empêchent ce geste, une iridoplastie ou une autre intervention peut être nécessaire. L’extraction du cristallin se discute après contrôle de la crise, ou dans certaines situations réfractaires ; elle comporte des risques spécifiques sur cet œil.')),
('La {prévention concerne aussi l’autre œil}. Après contrôle de la crise, rechercher une fermeture résiduelle et une atteinte du nerf optique. Les médicaments seuls ne garantissent pas l’absence de récidive.',paras('Pour le mécanisme primaire à bloc pupillaire, la recommandation européenne préconise l’iridotomie de l’autre œil phaque, idéalement durant la prise en charge de la crise et avant la sortie. Cette stratégie ne s’applique pas uniformément aux fermetures secondaires par épanchement.', 'Vérifier perméabilité de l’iridotomie, pression, angle et fonction visuelle. Un suivi prolongé peut rester nécessaire en raison de synéchies ou d’une lésion du système de drainage. Informer sur les symptômes de récidive et faire revoir les traitements pouvant favoriser une fermeture.')),
('Le {point clé} est d’agir immédiatement tout en identifiant le mécanisme. Un médicament qui convient au bloc pupillaire peut être inadapté à une fermeture secondaire. Le contrôle de la pression ne clôture pas à lui seul la prise en charge.',paras('Le traitement vise la vision, l’anatomie de l’angle et la sécurité générale. Les doses suisses citées sont distinguées des recommandations européennes et des gestes qui nécessitent une expertise ophtalmologique.'))]
quiz=[('Toute crise de fermeture d’angle est-elle déjà un glaucome constitué ?','Non, le glaucome implique une atteinte du nerf optique.'),('Des vomissements peuvent-ils accompagner une urgence oculaire ?','Oui.'),('L’absence de tonomètre autorise-t-elle à retarder l’orientation ?','Non.'),('Quel examen précise directement l’angle ?','La gonioscopie.'),('Pourquoi examiner l’autre œil ?','Pour rechercher une prédisposition et organiser la prévention.'),('Le topiramate peut-il intervenir dans une fermeture secondaire ?','Oui, notamment par épanchement uvéal et poussée postérieure.'),('La pilocarpine convient-elle à tous les mécanismes ?','Non, elle peut aggraver des formes cristalliniennes ou rétrocristalliniennes.'),('Pourquoi peut-elle être différée si la pression est très élevée ?','L’iris peut être ischémique et répondre insuffisamment.'),('La dose européenne d’acétazolamide est-elle automatiquement la dose AIPS ?','Non, les textes et les schémas doivent être distingués.'),('Quelles fonctions surveiller selon le traitement systémique ?','Fonction rénale, électrolytes et état acido-basique, notamment.'),('Quel est le rôle de l’iridotomie dans un bloc pupillaire ?','Créer un passage contournant le bloc.'),('Une pression abaissée dispense-t-elle du traitement du mécanisme ?','Non.'),('Un agent hyperosmotique est-il sans risque pour le cœur et les reins ?','Non, une évaluation préalable et une surveillance sont nécessaires.'),('Le suivi s’arrête-t-il quand la douleur cesse ?','Non, contrôler angle, pression, nerf optique et autre œil.')]
produire(9,parts,quiz,(1,21,26),acetazolamide)
